   345  int mg_mqtt_parse(const uint8_t *buf, size_t len, uint8_t version,
   346                    struct mg_mqtt_message *m) {
   347    uint8_t lc = 0, *p, *end;
   348    uint32_t n = 0, len_len = 0;
   349
   350    memset(m, 0, sizeof(*m));
   351    m->dgram.ptr = (char *) buf;
   352    if (len < 2) return MQTT_INCOMPLETE;
   353    m->cmd = (uint8_t)(buf[0] >> 4);
   354    m->qos = (buf[0] >> 1) & 3;
   355
   356    n = len_len = 0;
   357    p = (uint8_t *) buf + 1;
   358    while ((size_t)(p - buf) < len) {
   359      lc = *((uint8_t *) p++);
   360      n += (uint32_t)((lc & 0x7f) << 7 * len_len);
   361      len_len++;
   362      if (!(lc & 0x80)) break;
   363      if (len_len >= 4) return MQTT_MALFORMED;
   364    }
   365    end = p + n;
   366    if ((lc & 0x80) || (end > buf + len)) return MQTT_INCOMPLETE;
   367    m->dgram.len = (size_t)(end - buf);
   368
   369    switch (m->cmd) {
   370      case MQTT_CMD_CONNACK:
   371        if (end - p < 2) return MQTT_MALFORMED;
   372        m->ack = p[1];
   373        break;
   374      case MQTT_CMD_PUBACK:
   375      case MQTT_CMD_PUBREC:
   376      case MQTT_CMD_PUBREL:
   377      case MQTT_CMD_PUBCOMP:
   378      case MQTT_CMD_SUBSCRIBE:
   379      case MQTT_CMD_SUBACK:
   380      case MQTT_CMD_UNSUBSCRIBE:
   381      case MQTT_CMD_UNSUBACK:
   382        if (p + 2 > end) return MQTT_MALFORMED;
   383        m->id = (uint16_t)((((uint16_t) p[0]) << 8) | p[1]);
   384        p += 2;
   385        break;
   386      case MQTT_CMD_PUBLISH: {
   387        if (p + 2 > end) return MQTT_MALFORMED;
   388        m->topic.len = (uint16_t)((((uint16_t) p[0]) << 8) | p[1]);
   389        m->topic.ptr = (char *) p + 2;
   390        p += 2 + m->topic.len;
   391        if (p > end) return MQTT_MALFORMED;
   392        if (m->qos > 0) {
   393          if (p + 2 > end) return MQTT_MALFORMED;
   394          m->id = (uint16_t)((((uint16_t) p[0]) << 8) | p[1]);
   395          p += 2;
   396        }
   397        if (p > end) return MQTT_MALFORMED;
   398        if (version == 5 && p + 2 < end) {
   399          m->props_size = decode_variable_length((char *) p, &len_len);
   400          m->props_start = (size_t)(p + len_len - buf);
   401          p += len_len + m->props_size;
   402        }
   403        if (p > end) return MQTT_MALFORMED;
   404        m->data.ptr = (char *) p;
   405        m->data.len = (size_t)(end - p);
   406        break;
   407      }
   408      default:
   409        break;
   410    }
   411    return MQTT_OK;
   412  }
