   414  static void mqtt_cb(struct mg_connection *c, int ev, void *ev_data,
   415                      void *fn_data) {
   416    if (ev == MG_EV_READ) {
   417      for (;;) {
   418        uint8_t version = c->is_mqtt5 ? 5 : 4;
   419        struct mg_mqtt_message mm;
   420        int rc = mg_mqtt_parse(c->recv.buf, c->recv.len, version, &mm);
   421        if (rc == MQTT_MALFORMED) {
   422          MG_ERROR(("%lu MQTT malformed message", c->id));
   423          c->is_closing = 1;
   424          break;
   425        } else if (rc == MQTT_OK) {
   426          MG_VERBOSE(("%lu MQTT CMD %d len %d [%.*s]", c->id, mm.cmd,
   427                      (int) mm.dgram.len, (int) mm.data.len, mm.data.ptr));
   428          switch (mm.cmd) {
   429            case MQTT_CMD_CONNACK:
   430              mg_call(c, MG_EV_MQTT_OPEN, &mm.ack);
   431              if (mm.ack == 0) {
   432                MG_DEBUG(("%lu Connected", c->id));
   433              } else {
   434                MG_ERROR(("%lu MQTT auth failed, code %d", c->id, mm.ack));
   435                c->is_closing = 1;
   436              }
   437              break;
   438            case MQTT_CMD_PUBLISH: {
   439              MG_DEBUG(("%lu [%.*s] -> [%.*s]", c->id, (int) mm.topic.len,
   440                        mm.topic.ptr, (int) mm.data.len, mm.data.ptr));
   441              if (mm.qos > 0) {
   442                uint16_t id = mg_htons(mm.id);
   443                uint32_t remaining_len = sizeof(id);
   444                if (c->is_mqtt5) remaining_len += 1;
   445
   446                mg_mqtt_send_header(c, MQTT_CMD_PUBACK, 0, remaining_len);
   447                mg_send(c, &id, sizeof(id));
   448
   449                if (c->is_mqtt5) {
   450                  uint16_t zero = 0;
   451                  mg_send(c, &zero, sizeof(zero));
   452                }
   453              }
   454              mg_call(c, MG_EV_MQTT_MSG, &mm);
   455              break;
   456            }
   457          }
   458          mg_call(c, MG_EV_MQTT_CMD, &mm);
   459          mg_iobuf_del(&c->recv, 0, mm.dgram.len);
   460        } else {
   461          break;
   462        }
   463      }
   464    }
   465    (void) ev_data;
   466    (void) fn_data;
   467  }
